#import <Foundation/Foundation.h>
#import <Metal/Metal.h>
int main(void){ @autoreleasepool { id<MTLDevice> d=MTLCreateSystemDefaultDevice(); if(!d){fprintf(stderr,"METAL_NO_DEVICE\n"); return 2;} id<MTLCommandQueue> q=[d newCommandQueue]; if(!q){fprintf(stderr,"METAL_NO_COMMAND_QUEUE\n"); return 3;} MTLTextureDescriptor* td=[MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatRGBA8Unorm width:64 height:64 mipmapped:NO]; td.usage=MTLTextureUsageShaderRead|MTLTextureUsageRenderTarget; id<MTLTexture> t=[d newTextureWithDescriptor:td]; if(!t){fprintf(stderr,"METAL_NO_TEXTURE\n");return 4;} id<MTLCommandBuffer> cb=[q commandBuffer]; [cb commit]; [cb waitUntilCompleted]; if(cb.status==MTLCommandBufferStatusError){fprintf(stderr,"METAL_COMMAND_ERROR: %s\n",cb.error.localizedDescription.UTF8String);return 5;} printf("METAL_OK device=%s low_power=%d removable=%d unified_memory=%d\n",d.name.UTF8String,(int)d.lowPower,(int)d.removable,(int)d.hasUnifiedMemory); } return 0; }
